class Solution:
    def majorityFrequencyGroup(self, s: str) -> str:
        from collections import Counter, defaultdict
        cnt = Counter(s)
        groups = defaultdict(list)
        for ch, f in cnt.items():
            groups[f].append(ch)
        best = max(groups.items(), key=lambda kv: (len(kv[1]), kv[0]))
        return ''.join(best[1])

