class Solution {
public:
    string majorityFrequencyGroup(string s) {
        unordered_map<char,int> cnt;
        for (char c : s) cnt[c]++;
        unordered_map<int, vector<char>> groups;
        for (auto& [c, f] : cnt) groups[f].push_back(c);
        string best;
        int bs = 0, bk = 0;
        for (auto& [k, v] : groups)
            if ((int)v.size() > bs || ((int)v.size() == bs && k > bk)) {
                bs = v.size(); bk = k;
                best.assign(v.begin(), v.end());
            }
        return best;
    }
};

