class Solution {
    public String majorityFrequencyGroup(String s) {
        Map<Character,Integer> cnt = new HashMap<>();
        for (char c : s.toCharArray()) cnt.merge(c, 1, Integer::sum);
        Map<Integer,List<Character>> groups = new HashMap<>();
        for (var e : cnt.entrySet())
            groups.computeIfAbsent(e.getValue(), x -> new ArrayList<>()).add(e.getKey());
        String best = ""; int bs = 0, bk = 0;
        for (var e : groups.entrySet()) {
            int k = e.getKey(), sz = e.getValue().size();
            if (sz > bs || (sz == bs && k > bk)) {
                bs = sz; bk = k;
                StringBuilder sb = new StringBuilder();
                for (char c : e.getValue()) sb.append(c);
                best = sb.toString();
            }
        }
        return best;
    }
}

