var majorityFrequencyGroup = function(s) {
    const cnt = new Map();
    for (const c of s) cnt.set(c, (cnt.get(c) || 0) + 1);
    const groups = new Map();
    for (const [c, f] of cnt) {
        if (!groups.has(f)) groups.set(f, []);
        groups.get(f).push(c);
    }
    let best = [], bs = 0, bk = 0;
    for (const [k, v] of groups)
        if (v.length > bs || (v.length === bs && k > bk)) { bs = v.length; bk = k; best = v; }
    return best.join('');
};
